import re


class StackUnderflowError(Exception):
    pass


_NUMBER_RE = re.compile(r"^-?\d+$")


def _pop(stack, count):
    if len(stack) < count:
        raise StackUnderflowError("Insufficient number of items in stack")
    return [stack.pop() for _ in range(count)]


def _add(stack):
    b, a = _pop(stack, 2)
    stack.append(a + b)


def _sub(stack):
    b, a = _pop(stack, 2)
    stack.append(a - b)


def _mul(stack):
    b, a = _pop(stack, 2)
    stack.append(a * b)


def _div(stack):
    b, a = _pop(stack, 2)
    if b == 0:
        raise ZeroDivisionError("divide by zero")
    stack.append(a // b)


def _dup(stack):
    a = _pop(stack, 1)[0]
    stack.append(a)
    stack.append(a)


def _drop(stack):
    _pop(stack, 1)


def _swap(stack):
    b, a = _pop(stack, 2)
    stack.append(a)
    stack.append(b)


def _over(stack):
    b, a = _pop(stack, 2)
    stack.append(a)
    stack.append(b)
    stack.append(a)


_BUILTINS = {
    "+": _add,
    "-": _sub,
    "*": _mul,
    "/": _div,
    "dup": _dup,
    "drop": _drop,
    "swap": _swap,
    "over": _over,
}


def evaluate(input_data):
    stack = []
    words = {}

    def execute(token):
        if _NUMBER_RE.match(token):
            stack.append(int(token))
        elif token in words:
            for body_token in words[token]:
                execute(body_token)
        elif token in _BUILTINS:
            _BUILTINS[token](stack)
        else:
            raise ValueError("undefined operation")

    for line in input_data:
        tokens = line.lower().split()
        if tokens and tokens[0] == ":":
            name = tokens[1]
            if _NUMBER_RE.match(name):
                raise ValueError("illegal operation")
            body = []
            for token in tokens[2:]:
                if token in words:
                    # Resolve user-defined words to their current
                    # definition so that later redefinitions do not
                    # affect words that already referenced them.
                    body.extend(words[token])
                else:
                    body.append(token)
            words[name] = body
        else:
            for token in tokens:
                execute(token)

    return stack

